func toneColor(tone string) string {
	switch tone {
	case "green":
		return "var(--green)"
	case "blue":
		return "var(--accent)"
	case "amber":
		return "var(--amber)"
	case "purple":
		return "#c7b3ff"
	case "cyan":
		return "var(--cyan)"
	default:
		return "var(--text-3)"
	}
}

